from pathlib import Path
import json
import pandas as pd
out=Path(__file__).parent;d=pd.read_csv(out/'direction_summary.csv');ps=pd.read_csv(out/'direction_per_seed.csv');protocol=json.loads((out/'direction_protocol.json').read_text())
def rows(kind):
 return d[d.kind==kind].pivot(index=['end_s','period','axis'],columns='model',values=['direction_pct','amplitude_ratio','correlation','eligible_windows','eligible_flights']).sort_index()
s='''\n## 角速度同向性补充：两种旧口径\n\n对A/B×seed17/29四个best模型，各自重新推理完整156个固定validation窗口，共624次自主窗口预测；没有优化器更新。四次复算总分与保存值最大差7.11e-15，全部原生RMSE达到1e-8容差。模型初始belief由因果历史生成，未来角速度只用于评分。原生预测/实测时间序列保存于direction-*/window_*.npz。\n\n预测与实测共用决策时刻前最近且已发布的有效实测角速度作为ω0；其年龄满足原数据合同。Δω_pred=ω_pred(t)−ω0、Δω_true=ω_true(t)−ω0。这包含模型belief相对实测起点的误差，没有用未来观测重新定中心。A/B及两种子的窗口、原生观测时间、真值和起点均核对一致。\n\n### 口径1：端点增量\n\n沿用旧v16定义：|Δω_true|>0.01rad/s才进入方向分母；预测须同号且|Δω_pred|>0.01，预测过弱不算正确。0.01是报告死区，不是已标定噪声阈值。本次按现有原生目标，在名义20ms、200ms、500ms、1s、2s±30ms内取最近点；没有新建统一栅格或修改积分时刻，因此不是强行把旧20ms规则套成精确20ms观测。全体窗口仍参与幅值、RMSE和相关性。\n\n同向率：先航次内按符合真值门槛的窗口平均，再对有支持的航次等权，最后两个种子等权。相关性在端点是跨origins、航次等权的增量相关，不是时序波形相关。幅值比沿用旧报告的macro预测RMS变化/真实RMS变化。下表样本数是每个模型的独立窗口数，未将两个种子重复算作新增数据。\n\n| 时域 | 轴 | A同向率% | B同向率% | 有效窗口/航次 | A/B幅值比 | A/B增量相关 |\n|---|---|---:|---:|---:|---:|---:|\n'''
for (end,period,axis),r in rows('endpoint').iterrows():
 s+=f"| {period} | {axis} | {r['direction_pct','A']:.2f} | {r['direction_pct','B']:.2f} | {r['eligible_windows','A']:.0f}/{r['eligible_flights','A']:.0f} | {r['amplitude_ratio','A']:.3f}/{r['amplitude_ratio','B']:.3f} | {r['correlation','A']:.3f}/{r['correlation','B']:.3f} |\n"
s+='''\n### 口径2：区间平均变化\n\n沿用旧model_flight_response_diagnostic_v1的“先按真实dt平均Δω，再判断同号”定义。区间采用0–0.1s、0.1–0.3s、0.3–0.5s、0.5–1s，并扩展到1–2s；使用原生观测实际dt，区间边界处对时间权重裁切，没有插值生成目标。只用覆盖该区间（允许原生末点距名义端点≤30ms）的窗口，保留实际覆盖时长。\n\n弱变化门槛沿用历史TRAIN的固定q25值：p=0.159964、q=0.207299、r=0.060343rad/s，所有区间不变。它们不是当前9–10月train重新估计的q25，也不是噪声标定；本轮没有在validation上重拟合或搜索门槛。与旧报告一致，只要求预测区间均值同号，不对预测均值另加幅值门槛，所以必须同时看幅值比。历史数据和模型不同，不能直接把本表百分比与旧报告96%等数值排名。\n\n区间相关性是各窗口内按实际dt加权、去均值后的波形相关，先航次等权，再种子等权；与上面的端点跨origins相关性不同。方向列仅强变化子集，幅值与相关列仍覆盖全部合格窗口，两者分母不同。\n\n| 区间 | 轴 | A同向率% | B同向率% | 有效窗口/航次 | A/B幅值比 | A/B波形相关 |\n|---|---|---:|---:|---:|---:|---:|\n'''
labels={'early':'0–0.1s','middle':'0.1–0.3s','late':'0.3–0.5s','extended':'0.5–1s','long':'1–2s'}
for (end,period,axis),r in rows('interval').iterrows():
 s+=f"| {labels[period]} | {axis} | {r['direction_pct','A']:.2f} | {r['direction_pct','B']:.2f} | {r['eligible_windows','A']:.0f}/{r['eligible_flights','A']:.0f} | {r['amplitude_ratio','A']:.3f}/{r['amplitude_ratio','B']:.3f} | {r['correlation','A']:.3f}/{r['correlation','B']:.3f} |\n"
s+='''\n### 结果解读\n\n1. 两种方向口径均未支持完整A相对B的稳定全面改进。2s端点p：A56.41%、B61.54%，两个种子都是A较差；q：A75.00%、B72.37%；r：A78.95%、B80.26%。这不是一个整体一致改善的模式。\n2. 区间平均方向可以很高，同时动态细节很差。1–2s强变化p子集为29窗口/29航次，A100%、B98.28%；但全部39窗口/39航次的p波形相关仅0.106/0.276，幅值比0.662/0.676。不能把方向分母中被排除的弱变化忘掉，也不能用100%掩盖波形和幅值问题。\n3. q的短期区间波形相关较高（0–0.1s约0.884/0.892，0.3–0.5s约0.800/0.801），延长到1–2s降至0.380/0.386，且幅值比0.785/0.814。\n4. r在0.3–0.5s、0.5–1s区间A平均同向率较高，但1–2s退化到90.32%，B为96.77%，两个种子都支持这一长区间退化。\n5. 所有结论是原记录控制条件下的运动响应一致性；相对起点的净变化仍混合惯性、其他控制和扰动，不能直接等同真实舵效方向正确率，也没有证明闭环MPC有效。\n\n![两种同向率](angular_direction.png)\n\n下面例图事先按窗口身份选取：seed17、2s组按flight_id排序的中位航次，不按误差挑选。只用来说明波形形态，不能替代上面的全部航次统计。\n\n![固定身份窗口角速度增量](angular_direction_example.png)\n\n完整分母、逐种子和逐航次结果：direction_windows.csv、direction_per_flight.csv、direction_per_seed.csv、direction_summary.csv。方向死区边界自检通过，A/B原生时间/真值/起点及方向有效窗口分母逐项相同。\n'''
p=out/'report_zh.md';content=p.read_text();marker='\n## 角速度同向性补充：两种旧口径';p.write_text(content.split(marker)[0]+s)
print(p)
